'use client';

import { useCallback, useEffect, useRef, useState, type ReactNode, type FormEvent } from 'react';
import { ArrowUpRight, ArrowRight, ArrowLeft, Bell, Boxes, Check, CheckCheck, CheckCircle2, ChevronDown, ChevronRight, CircleHelp, ClipboardCheck, ClipboardList, Clock3, Download, FileCheck2, FileText, Globe2, LayoutDashboard, Leaf, Loader2, Menu, MessageCircle, Package, Plus, Search, Send, ShieldCheck, SlidersHorizontal, Store, Truck, Users, Wallet, X, AlertTriangle, MapPin, ExternalLink, CircleDot, RefreshCw } from 'lucide-react';
import type { Actor, Role, SupplyState, WorkspaceResponse, Product, Order, Demand, Quote, Supplier } from '../lib/supply/types';

const money = (value: number) => new Intl.NumberFormat('zh-CN', { style: 'currency', currency: 'CNY', maximumFractionDigits: 2 }).format(value / 100);
const number = (value: number) => new Intl.NumberFormat('zh-CN').format(value);
const dateText = (value: string) => value ? new Date(value).toLocaleDateString('zh-CN', { month: '2-digit', day: '2-digit', timeZone: 'Asia/Shanghai' }) : '待确认';
const day = (offset = 0) => new Date(Date.now() + offset * 86400000).toISOString().slice(0, 10);
const categories = ['家居日用', '家纺布艺', '箱包配饰', '其他'];
const roles: { id: Role; title: string; subtitle: string }[] = [{ id: 'operations', title: '平台运营', subtitle: '组织交易与交付' }, { id: 'supplier', title: '供货商户', subtitle: '专注商品与供货' }, { id: 'buyer', title: '海外采购', subtitle: '选品、采购与补货' }];
const nav = [
  { id: 'dashboard', title: '工作台', icon: LayoutDashboard },
  { id: 'products', title: '商品与选品', icon: Package },
  { id: 'demands', title: '采购需求', icon: ClipboardList },
  { id: 'orders', title: '供货订单', icon: Boxes },
  { id: 'logistics', title: '集货与物流', icon: Truck },
  { id: 'documents', title: '关务与资料', icon: FileCheck2 },
  { id: 'settlements', title: '收付款与结算', icon: Wallet },
  { id: 'suppliers', title: '合作商户', icon: Users },
  { id: 'issues', title: '异常与售后', icon: ShieldCheck },
];
const pageDescriptions: Record<string, string> = { products: '把好商品整理好，让每一次供货都有据可依。', demands: '从真实采购需求出发，找到适合的商品。', orders: '一张订单，串起供货、交付与结算。', logistics: '从昆明集货，到海外签收，每一步清楚可见。', documents: '单证、执行主体和办理结果，始终与订单关联。', settlements: '应付、应结与付款记录分开核对，商户平台费为零。', suppliers: '免费申请，按商品与履约能力审核。', issues: '发现问题，明确责任，跟进到有结果。', service: '一个入口，跟进每一项服务请求。' };
type Modal = { type: string; product?: Product; order?: Order; demand?: Demand; quote?: Quote; id?: string; supplierId?: string; title?: string } | null;
const dueFor = (o: Order, sid: string) => o.lines.filter(l => l.supplierId === sid).reduce((a, l) => a + (l.unitCost ?? l.unitPrice) * l.quantity, 0);
const paidFor = (s: SupplyState, oid: string, sid: string) => s.settlements.filter(x => x.orderId === oid && x.supplierId === sid).reduce((a, x) => a + x.amount, 0);

function Badge({ children, tone }: { children: ReactNode; tone?: string }) {
  const text = String(children);
  const t = tone || (['可供货', '已准入', '已核实', '已放行', '已归档', '已解决', '已完成', '已交付', '已关闭', '已签收', '已通过', '已接受', '已成交'].includes(text) ? 'green' : ['存在差异', '待补充'].includes(text) ? 'red' : ['运输中', '已报价', '待发运'].includes(text) ? 'blue' : 'amber');
  return <span className={`badge ${t}`}><i />{children}</span>;
}
function ProductArt({ kind, small = false }: { kind: string; small?: boolean }) {
  return <div className={`product-art ${kind} ${small ? 'small' : ''}`} aria-hidden="true"><svg viewBox="0 0 220 160">
    <ellipse cx="110" cy="137" rx="66" ry="9" fill="#283d3010" />
    {kind === 'basket' && <g><path d="M43 62 60 132 167 132 182 62Z" fill="#d6c5a5" /><ellipse cx="112" cy="63" rx="70" ry="23" fill="#c2ac87" /><ellipse cx="112" cy="61" rx="62" ry="17" fill="#ad9575" /><path d="M50 78Q110 105 175 78M53 92Q110 118 172 92M57 107Q111 130 169 107M62 121Q111 141 166 121" stroke="#f0e6d4" strokeWidth="3" fill="none" />{[70,85,100,115,130,145,160].map(x => <path key={x} d={`M${x} 84L${x + (110 - x) / 8} 131`} stroke="#f0e6d4" strokeWidth="2" />)}<path d="M62 58Q61 24 86 25M140 26Q163 22 164 57" fill="none" stroke="#bba482" strokeWidth="7" /></g>}
    {kind === 'towel' && <g transform="rotate(-10 110 90)"><rect x="42" y="59" width="132" height="66" rx="9" fill="#cac6b9" /><rect x="47" y="46" width="125" height="68" rx="7" fill="#e3dfd0" /><rect x="54" y="33" width="119" height="68" rx="7" fill="#f7f3e6" /><path d="M61 44H160M61 50H160M61 85H160M61 91H160" stroke="#dbd5c4" strokeWidth="2" /><path d="M166 38V97" stroke="#fffdf4" strokeWidth="3" /></g>}
    {kind === 'bag' && <g><path d="M62 60H158L171 136H49Z" fill="#d9cdb6" /><path d="M74 67V42C74 15 143 15 143 42V67" fill="none" stroke="#b3a58c" strokeWidth="9" /><path d="M67 65L58 130H162L153 65" fill="#e8dec9" /><path d="M73 75V128M145 75V128" stroke="#d2c4a8" strokeWidth="2" /><path d="M86 91H132V120H86Z" fill="#dacfba" /><path d="M86 91H132" stroke="#baac90" /></g>}
    {kind === 'bottle' && <g><rect x="82" y="39" width="58" height="96" rx="15" fill="#92a18a" /><rect x="84" y="30" width="54" height="21" rx="6" fill="#566c58" /><path d="M96 58V116" stroke="#b9c4ae" strokeWidth="6" strokeLinecap="round" /><path d="M138 38Q165 42 151 64" fill="none" stroke="#566c58" strokeWidth="5" /><rect x="91" y="24" width="39" height="9" rx="4" fill="#71836b" /></g>}
    {kind === 'pillow' && <g transform="rotate(-8 110 80)"><path d="M54 28Q110 37 168 28Q156 83 168 137Q111 126 53 138Q65 81 54 28" fill="#a9b4a0" /><path d="M71 35Q79 82 69 132M91 36Q97 82 90 129M114 36V129M137 34Q130 83 137 131M156 32Q146 80 156 134" fill="none" stroke="#e4e6d7" strokeWidth="8" /><path d="M56 31Q110 40 165 31" fill="none" stroke="#8b9883" /></g>}
    {kind === 'organizer' && <g transform="rotate(-9 110 90)"><rect x="40" y="35" width="114" height="88" rx="13" fill="#a6aaa2" /><rect x="46" y="43" width="100" height="70" rx="9" fill="#bdc1b6" /><rect x="101" y="79" width="80" height="55" rx="9" fill="#7a8c81" /><rect x="105" y="84" width="69" height="43" rx="7" fill="#95a398" /><rect x="51" y="99" width="72" height="41" rx="7" fill="#ddd9c9" /><path d="M56 104H116M46 42H143M108 84H174" stroke="#f8f7ef" strokeWidth="2" /></g>}
  </svg></div>;
}
function RouteGraphic() { return <div className="route-graphic" aria-label="示意线路：昆明，经万象，至曼谷"><svg viewBox="0 0 420 190"><g stroke="#ffffff0d" strokeWidth="1">{[30,65,100,135,170].map(y => <path key={y} d={`M0 ${y}H420`} />)}{[30,80,130,180,230,280,330,380].map(x => <path key={x} d={`M${x} 0V190`} />)}</g><path d="M58 47C110 45 90 108 195 104S287 166 357 135" fill="none" stroke="#b6ce91" strokeWidth="2" strokeDasharray="5 5"/><circle cx="58" cy="47" r="13" fill="#ffffff10"/><circle cx="58" cy="47" r="5" fill="#e3edbc"/><circle cx="195" cy="104" r="5" fill="#d5e4b1"/><circle cx="357" cy="135" r="16" fill="#d3eaa820"/><circle cx="357" cy="135" r="6" fill="#d3eaa8"/><text x="42" y="26" fill="#fff" fontSize="13">昆明</text><text x="178" y="84" fill="#d9e7dd" fontSize="12">万象</text><text x="338" y="171" fill="#fff" fontSize="13">曼谷</text><g transform="translate(245 109) rotate(17)"><rect width="23" height="16" rx="3" fill="#c7df9f"/><path d="M23 5H29L33 11V16H23Z" fill="#a2bd7d"/><circle cx="6" cy="18" r="3" fill="#e8f0d7"/><circle cx="27" cy="18" r="3" fill="#e8f0d7"/></g></svg><span>中国 · 云南 <ArrowRight size={12}/> 泰国</span></div>; }

function Dialog({ title, children, onClose, wide = false }: { title: string; children: ReactNode; onClose: () => void; wide?: boolean }) {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => { const previous = document.activeElement as HTMLElement; const root = ref.current; const first = root?.querySelector<HTMLElement>('input, select, textarea, button'); first?.focus(); const handle = (e: KeyboardEvent) => { if (e.key === 'Escape') onClose(); if (e.key === 'Tab' && root) { const items = [...root.querySelectorAll<HTMLElement>('button:not([disabled]), input, select, textarea, a[href]')]; const first = items[0], last = items[items.length - 1]; if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last?.focus(); } else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first?.focus(); } } }; document.addEventListener('keydown', handle); const old = document.body.style.overflow; document.body.style.overflow = 'hidden'; return () => { document.removeEventListener('keydown', handle); document.body.style.overflow = old; previous?.focus(); }; }, [onClose]);
  return <div className="modal-overlay" onMouseDown={e => { if (e.target === e.currentTarget) onClose(); }}><div ref={ref} className={`dialog ${wide ? 'wide' : ''}`} role="dialog" aria-modal="true" aria-label={title}><div className="dialog-heading"><div><span className="eyebrow">LUOSI TRADE</span><h2>{title}</h2></div><button className="icon-button" onClick={onClose} aria-label="关闭"><X size={21}/></button></div>{children}</div></div>;
}
function Field({ label, children, hint, full = false }: { label: string; children: ReactNode; hint?: string; full?: boolean }) { return <label className={`field ${full ? 'full' : ''}`}><span>{label}</span>{children}{hint && <small>{hint}</small>}</label>; }

export default function SupplyApp({ displayName }: { displayName: string }) {
  const [workspace, setWorkspace] = useState<WorkspaceResponse | null>(null);
  const [actor, setActor] = useState<Actor>({ role: 'operations', entityId: 'operations' });
  const [page, setPage] = useState('dashboard'); const [query, setQuery] = useState(''); const [filter, setFilter] = useState('全部');
  const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  const [toast, setToast] = useState(''); const [modal, setModal] = useState<Modal>(null); const [mobileOpen, setMobileOpen] = useState(false);
  const [formError, setFormError] = useState(''); const [quoteLineCount, setQuoteLineCount] = useState(1);
  const [supplierOptions, setSupplierOptions] = useState<{id: string; name: string}[]>([]);
  const [buyerOptions, setBuyerOptions] = useState<{id: string; name: string}[]>([]);
  const s = workspace?.state;
  const supplier = s?.suppliers.find(x => x.id === actor.entityId);
  const currentRole = roles.find(r => r.id === actor.role)!;
  const pageTitle = page === 'service' ? '帮助与服务' : actor.role === 'buyer' && page === 'orders' ? '采购订单' : actor.role === 'supplier' && page === 'products' ? '我的货品' : actor.role === 'supplier' && page === 'settlements' ? '我的结算' : nav.find(n => n.id === page)?.title;
  const isOps = actor.role === 'operations'; const isSupplier = actor.role === 'supplier'; const isBuyer = actor.role === 'buyer';
  const allowedNav = nav.filter(n => !(isBuyer && ['suppliers', 'documents', 'settlements'].includes(n.id)) && !(isSupplier && ['suppliers', 'documents'].includes(n.id)));
  const navigate = (next: string) => { setPage(next); setQuery(''); setFilter('全部'); setMobileOpen(false); };
  const dismiss = useCallback(() => { setModal(null); setFormError(''); }, []);
  const open = (value: Modal) => { setFormError(''); setQuoteLineCount(1); setModal(value); };
  const load = useCallback(async (signal?: AbortSignal) => {
    setLoading(true); setError('');
    try { const res = await fetch(`/api/workspace?role=${actor.role}&entityId=${encodeURIComponent(actor.entityId)}`, { signal }); const result = await res.json() as WorkspaceResponse & { error?: string }; if (!res.ok) throw new Error(result.error || '读取失败'); setWorkspace(result); if (actor.role === 'operations') { setSupplierOptions(result.state.suppliers.map((x: Supplier) => ({ id: x.id, name: x.name }))); setBuyerOptions(result.state.buyers); } }
    catch (e) { if ((e as Error).name !== 'AbortError') setError((e as Error).message); }
    finally { if (!signal?.aborted) setLoading(false); }
  }, [actor]);
  useEffect(() => { const ctrl = new AbortController(); load(ctrl.signal); return () => ctrl.abort(); }, [load]);
  useEffect(() => { if (!toast) return; const timer = setTimeout(() => setToast(''), 4500); return () => clearTimeout(timer); }, [toast]);
  const changeRole = (role: Role) => { setWorkspace(null); setActor({ role, entityId: role === 'supplier' ? supplierOptions[0]?.id || 'sup-1' : role === 'buyer' ? buyerOptions[0]?.id || 'buyer-1' : 'operations' }); navigate('dashboard'); };
  async function command(action: string, payload: unknown) {
    if (!workspace || busy) return false; setBusy(true); setFormError('');
    try { const res = await fetch('/api/workspace', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ action, payload, actor, revision: workspace.revision }) }); const result = await res.json() as WorkspaceResponse & { error?: string }; if (!res.ok) { if (res.status === 409) await load(); throw new Error(result.error || '保存失败'); } setWorkspace(result); if (isOps) setSupplierOptions(result.state.suppliers.map((x: Supplier) => ({ id: x.id, name: x.name }))); setToast('已保存，相关业务记录已更新'); dismiss(); return true; }
    catch (e) { setFormError((e as Error).message); setToast((e as Error).message); return false; } finally { setBusy(false); }
  }
  const matches = (value: unknown) => JSON.stringify(value).toLowerCase().includes(query.toLowerCase());
  const orders = s?.orders.filter(matches) || [];
  const products = s?.products.filter(p => matches(p) && (filter === '全部' || p.status === filter || p.category === filter)) || [];
  const activeIssues = s?.issues.filter(i => i.status === '待处理') || [];
  const waitingProducts = s?.products.filter(p => p.status !== '可供货') || [];
  const settlementRows = s ? s.orders.filter(o => ['已交付', '已关闭'].includes(o.status)).flatMap(o => [...new Set(o.lines.map(l => l.supplierId))].map(sid => ({ order: o, supplierId: sid, due: dueFor(o, sid), paid: paidFor(s, o.id, sid) }))) : [];
  const pendingTotal = settlementRows.reduce((a, r) => a + r.due - r.paid, 0);
  const supplierName = (id: string) => s?.suppliers.find(x => x.id === id)?.name || '供货商户';
  const buyerName = (id: string) => s?.buyers.find(x => x.id === id)?.name || '泰国采购渠道';
  const orderActions = (o: Order) => <div className="actions-wrap">
    {(isOps || isSupplier) && o.status === '待确认' && [...new Set(o.lines.map(l => l.supplierId))].filter(id => !o.confirmedSuppliers.includes(id)).map(id => <button key={id} className="btn primary small-btn" disabled={busy} onClick={() => open({ type: 'confirmSupply', order: o, supplierId: id })}><Check size={15}/>确认供货{isOps ? ` · ${supplierName(id)}` : ''}</button>)}
    {isOps && o.payment === '待核实' && <button className="btn small-btn" onClick={() => open({ type: 'verifyPayment', order: o })}>登记收款核验</button>}
    {isOps && o.status === '待启动' && <button className="btn primary small-btn" disabled={busy} onClick={() => command('startSupply', { id: o.id })}>启动供货</button>}
    {(isOps || isSupplier) && o.status === '备货中' && [...new Set(o.lines.map(l => l.supplierId))].filter(id => !o.deliveredSuppliers.includes(id)).map(id => <button key={id} className="btn primary small-btn" onClick={() => open({ type: 'warehouseDelivery', order: o, supplierId: id })}>登记交货{isOps ? ` · ${supplierName(id)}` : ''}</button>)}
    {isOps && o.status === '待验货' && <button className="btn primary small-btn" onClick={() => open({ type: 'inspect', order: o })}>登记验货</button>}
    {isOps && o.status === '待发运' && <button className="btn primary small-btn" onClick={() => open({ type: 'dispatch', order: o })}>登记发运</button>}
    {(isOps || isBuyer) && o.status === '运输中' && <button className="btn primary small-btn" onClick={() => open({ type: 'receive', order: o })}>确认签收</button>}
    {isOps && o.status === '已交付' && o.lines.every(l => dueFor(o, l.supplierId) === paidFor(s!, o.id, l.supplierId)) && <button className="btn small-btn" disabled={busy} onClick={() => command('closeOrder', { id: o.id })}>关闭订单</button>}
    <button className="btn small-btn" onClick={() => open({ type: 'createIssue', order: o })}>反馈异常</button>
  </div>;
  const empty = (title = '暂无相关记录', note = '调整筛选条件，或从右上方开始创建。') => <div className="empty"><Package size={30}/><h3>{title}</h3><p>{note}</p></div>;
  const orderTable = (list: Order[], compact = false) => list.length ? <div className="table-scroll"><table className="data-table"><thead><tr><th>订单 / 商品</th>{!compact && <th>{isSupplier ? '采购渠道' : '供货商户'}</th>}<th>{isSupplier ? '供货金额' : '订单金额'}</th><th>订单状态</th>{!compact && <th>物流 / 款项</th>}<th>约定到货</th><th /></tr></thead><tbody>{list.map(o => <tr key={o.id}><td><button className="table-main" onClick={() => open({ type: 'orderDetail', order: o })}>{o.id}</button><span className="table-sub">{o.lines[0]?.name}{o.lines.length > 1 ? ` 等 ${o.lines.length} 款商品` : ` × ${o.lines[0]?.quantity}`}</span></td>{!compact && <td>{isSupplier ? buyerName(o.buyerId) : isBuyer ? '螺蛳湾精选供货' : [...new Set(o.lines.map(l => supplierName(l.supplierId)))].join('、')}</td>}<td className="numeric">{money(o.total)}</td><td><Badge>{o.status}</Badge></td>{!compact && <td><span className="table-sub dark">{o.logistics}</span><span className="table-sub">收款{o.payment}</span></td>}<td className="muted">{dateText(o.dueDate)}</td><td><button className="icon-button" aria-label={`查看订单 ${o.id}`} onClick={() => open({ type: 'orderDetail', order: o })}><ArrowUpRight size={18}/></button></td></tr>)}</tbody></table></div> : empty('暂时没有订单', '采购方确认报价后，供货订单会出现在这里。');
  function exportOrders() { if (!s) return; const protect = (value: string) => /^[=+\-@\t\r]/.test(value) ? `'${value}` : value; const rows = [['订单编号', '商品', '金额（人民币元）', '订单状态', '物流状态', '收款状态'], ...s.orders.map(o => [o.id, o.lines.map(l => l.name).join(' / '), String(o.total / 100), o.status, o.logistics, o.payment])]; const csv = '\ufeff' + rows.map(r => r.map(v => `"${protect(v).replace(/"/g, '""')}"`).join(',')).join('\r\n'); const a = document.createElement('a'); const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' })); a.href = url; a.download = `供货订单-${day()}.csv`; a.click(); URL.revokeObjectURL(url); setToast('已导出当前身份可见的订单'); }

  function renderDashboard() {
    if (!s) return null;
    const confirmCount = s.orders.filter(o => o.status === '待确认').length;
    const tasks = [
      ...(isOps || isSupplier ? [{ title: isSupplier ? '完善商品资料' : '商品等待审核', count: waitingProducts.length, note: '确认规格、供货条件与必要资料', icon: Package, page: 'products', tone: 'amber' }] : []),
      { title: isBuyer ? '采购报价待确认' : '供货订单待确认', count: isBuyer ? s.quotes.filter(q => q.status === '待确认').length : confirmCount, note: '确认价格、数量和交付安排', icon: ClipboardCheck, page: isBuyer ? 'demands' : 'orders', tone: 'blue' },
      { title: '异常需要处理', count: activeIssues.length, note: '处理差异后继续履约', icon: AlertTriangle, page: 'issues', tone: 'red' },
    ];
    const stats = isBuyer ? [{ label: '有效采购需求', value: String(s.demands.length), sub: '需求与采购条件已留存', icon: ClipboardList }, { label: '待确认报价', value: String(s.quotes.filter(q => q.status === '待确认').length), sub: '查看费用与交付条件', icon: FileText }, { label: '履约中订单', value: String(s.orders.filter(o => !['已交付','已关闭'].includes(o.status)).length), sub: '供货与物流分别跟进', icon: Truck }, { label: '已交付订单', value: String(s.orders.filter(o => ['已交付','已关闭'].includes(o.status)).length), sub: '可继续发起补货需求', icon: CheckCircle2 }] : [{ label: '可供货商品', value: String(s.products.filter(p => p.status === '可供货').length), sub: `${waitingProducts.length} 款待审核或补充资料`, icon: Package }, { label: '履约中订单', value: String(s.orders.filter(o => !['已交付','已关闭'].includes(o.status)).length), sub: `${s.orders.filter(o => o.status === '运输中').length} 笔正在跨境运输`, icon: Boxes }, { label: isSupplier ? '待收货款' : '商户待结款', value: money(pendingTotal), sub: '已交付订单的未结余额', icon: Wallet }, { label: '待处理异常', value: String(activeIssues.length), sub: activeIssues.length ? '请优先跟进阻断事项' : '当前没有待处理异常', icon: ShieldCheck }];
    return <>
      <section className="welcome"><div><div className="eyebrow">YOUR NEXT DESTINATION</div><h1>{isSupplier ? '好货在手，生意向外。' : isBuyer ? '好商品，从这里出发。' : '让好商品，走向更远。'}</h1><p>{isOps ? '连接螺蛳湾商户与海外采购，让每一笔交易有序发生。' : isSupplier ? '你专注供货，我们组织海外渠道与交易服务。' : '精选螺蛳湾货源，一站跟进选品、采购与交付。'}</p><div className="hero-actions"><button className="btn hero-btn" onClick={() => isBuyer ? open({ type: 'createDemand' }) : navigate('demands')}>{isBuyer ? '发布采购需求' : '查看采购需求'}<ArrowUpRight size={17}/></button><span><ShieldCheck size={15}/>商户免费入驻 · 按供货能力审核</span></div></div><RouteGraphic/></section>
      <div className="stats-grid">{stats.map(x => <div className="stat" key={x.label}><div className="stat-top"><span>{x.label}</span><x.icon size={18}/></div><strong>{x.value}</strong><small>{x.sub}</small></div>)}</div>
      <div className="dashboard-grid"><section className="panel orders-panel"><div className="panel-heading"><div><h2>订单进展 <span className="count">{s.orders.length}</span></h2><p>从供货确认到交付，关注每个关键节点</p></div><button className="text-button" onClick={() => navigate('orders')}>全部订单<ArrowRight size={15}/></button></div><div className="progress-overview">{['待确认','备货中','待验货','运输中','已交付'].map((label, i) => <button key={label} onClick={() => { navigate('orders'); setFilter(label); }}><span className={`progress-line p${i}`} /><b>{s.orders.filter(o => o.status === label).length.toString().padStart(2,'0')}</b><small>{label}</small></button>)}</div>{orderTable(s.orders.filter(matches).slice(0, 4), true)}</section>
      <section className="panel todo-panel"><div className="panel-heading"><div><h2>需要你处理</h2><p>把重要的事放在前面</p></div><span className="round-icon"><Clock3 size={17}/></span></div><div className="todo-list">{tasks.map(t => <button className="todo-item" key={t.title} onClick={() => navigate(t.page)}><span className={`todo-icon ${t.tone}`}><t.icon size={18}/></span><span><b>{t.title}<em>{t.count}</em></b><small>{t.note}</small></span><ChevronRight size={16}/></button>)}</div><div className="service-mini"><div className="avatar small-avatar">服</div><div><b>供货服务台</b><small>问题留记录，进度随时看</small></div><button className="icon-button" aria-label="联系服务台" onClick={() => navigate('service')}><MessageCircle size={20}/></button></div></section></div>
      <section className="panel"><div className="panel-heading"><div><h2>{isSupplier ? '我的供货商品' : '精选供货商品'}</h2><p>清楚的规格，可靠的供货条件</p></div><button className="text-button" onClick={() => navigate('products')}>查看商品<ArrowRight size={15}/></button></div><div className="featured-products">{s.products.filter(matches).slice(0,4).map(p => <button className="featured-product" key={p.id} onClick={() => open({ type: 'productDetail', product: p })}><ProductArt kind={p.artwork} small/><div><b>{p.name}</b><small>{p.category} · {p.moq} {p.unit}起订</small><strong>{isBuyer ? '查看供货条件' : money(p.price)}{!isBuyer && <em> / {p.unit}</em>}</strong></div></button>)}</div></section>
    </>;
  }
  function renderProducts() { return <><div className="toolbar"><div className="tabs">{['全部','可供货','待审核','待补充'].filter(t => !isBuyer || t === '全部').map(t => <button className={filter === t ? 'active' : ''} key={t} onClick={() => setFilter(t)}>{t}</button>)}</div><label className="filter-select"><SlidersHorizontal size={15}/><select aria-label="商品分类" value={categories.includes(filter) ? filter : ''} onChange={e => setFilter(e.target.value || '全部')}><option value="">全部品类</option>{categories.map(c => <option key={c}>{c}</option>)}</select></label></div><div className="product-grid">{products.map(p => <article className="product-card" key={p.id}><button className="product-image-button" onClick={() => open({ type: 'productDetail', product: p })}><ProductArt kind={p.artwork}/><div className="product-badge"><Badge>{p.status}</Badge></div></button><div className="product-body"><span className="category-label">{p.category}</span><button className="product-title" onClick={() => open({ type: 'productDetail', product: p })}>{p.name}<ArrowUpRight size={15}/></button><p>{p.spec}</p><div className="product-price"><strong>{isBuyer ? '询价获取报价' : money(p.price)}</strong>{!isBuyer && <small> / {p.unit}</small>}</div><div className="product-meta"><span>{p.moq} {p.unit}起订</span><span>{p.leadDays} 天备货</span><span>可供 {number(p.stock)}</span></div><div className="product-footer"><span>{isBuyer ? '螺蛳湾精选货源' : supplierName(p.supplierId)}</span><button className="text-button" onClick={() => isBuyer ? open({ type: 'createDemand', product: p }) : open({ type: isOps && p.status !== '可供货' ? 'reviewProduct' : 'updateProduct', product: p })}>{isBuyer ? '发起采购' : isOps && p.status !== '可供货' ? '审核' : '编辑'}<ChevronRight size={13}/></button></div></div></article>)}</div>{!products.length && empty()}</>; }
  function renderDemands() { return <><div className="section-note"><Globe2 size={18}/><span>泰国首发 · 需求明确后组织选品与报价，商户供货资格与付费会员无关。</span></div><div className="demand-grid">{s!.demands.filter(matches).map(d => <article className="panel demand-card" key={d.id}><div className="demand-top"><span className="country-label">TH <span>泰国采购</span></span><Badge>{d.status}</Badge></div><h3>{d.title}</h3><p>{d.requirements}</p><div className="demand-numbers"><div><small>需求数量</small><strong>{number(d.quantity)}<em> 件</em></strong></div><div><small>目标单价</small><strong>{d.budget ? money(d.budget) : '面议'}</strong></div><div><small>期望到货</small><strong>{dateText(d.dueDate)}</strong></div></div><div className="demand-bottom"><span><MapPin size={13}/>{d.destination}</span>{isOps && d.status !== '已成交' ? <button className="btn small-btn primary" onClick={() => open({ type: 'createQuote', demand: d })}>组织报价<ArrowUpRight size={14}/></button> : <button className="text-button" onClick={() => open({ type: 'demandDetail', demand: d })}>查看需求<ArrowRight size={14}/></button>}</div></article>)}</div>{s!.quotes.length > 0 && <section className="panel spaced"><div className="panel-heading"><div><h2>报价记录</h2><p>金额为人民币，具体费用与条款以报价版本为准</p></div></div><div className="table-scroll"><table className="data-table"><thead><tr><th>报价编号</th><th>商品</th><th>报价总额</th><th>有效期</th><th>状态</th><th/></tr></thead><tbody>{s!.quotes.filter(matches).map(q => <tr key={q.id}><td>{q.id}</td><td>{q.lines.map(l => l.name).join('、')}</td><td>{money(q.total)}</td><td>{dateText(q.validUntil)}</td><td><Badge>{q.status}</Badge></td><td><button className="text-button" onClick={() => open({ type: 'quoteDetail', quote: q })}>查看报价</button></td></tr>)}</tbody></table></div></section>}{!s!.demands.length && empty('暂无采购需求', '采购方发布需求后，运营可以组织商品报价。')}</>; }
  function renderLogistics() { const list = orders.filter(o => !['待确认','待启动'].includes(o.status)); return <><div className="section-note"><Truck size={18}/><span>当前使用人工核实的履约记录。承运商轨迹接口尚未接入。</span></div><div className="shipment-grid">{list.map(o => <section className="panel shipment-card" key={o.id}><div className="shipment-head"><button className="table-main" onClick={() => open({ type: 'orderDetail', order: o })}>{o.id}</button><Badge>{o.logistics}</Badge></div><div className="shipment-route"><div><small>集货地</small><b>昆明 · 螺蛳湾</b></div><span><Truck size={20}/><i/></span><div><small>目的地</small><b>{o.destination}</b></div></div><div className="tracking"><span className={o.deliveredSuppliers.length ? 'done' : ''}>国内交货</span><span className={o.inspection === '已通过' ? 'done' : ''}>验货通过</span><span className={o.customs === '已放行' ? 'done' : ''}>通关放行</span><span className={['运输中','已签收'].includes(o.logistics) ? 'done' : ''}>跨境运输</span><span className={o.logistics === '已签收' ? 'done' : ''}>海外签收</span></div><div className="shipment-info"><span>承运服务 <b>{o.carrier || '待安排'}</b></span><span>运单号 <b>{o.waybill || '待发运后登记'}</b></span><span>预计到达 <b>{dateText(o.eta)}</b></span></div><div className="shipment-actions">{orderActions(o)}</div></section>)}</div>{!list.length && empty('暂无履约中的订单')}</>; }
  function renderDocuments() { return <><div className="section-note"><FileCheck2 size={18}/><span>登记经过核实的办理结果与凭证编号；各订单的关务和税务状态独立管理。</span></div><section className="panel"><div className="table-scroll"><table className="data-table"><thead><tr><th>订单</th><th>出口 / 进口主体</th><th>关务状态</th><th>税务资料</th><th>办理记录</th></tr></thead><tbody>{orders.map(o => <tr key={o.id}><td><button className="table-main" onClick={() => open({ type: 'orderDetail', order: o })}>{o.id}</button><span className="table-sub">{o.lines[0]?.name}</span></td><td><span className="table-sub dark">{o.parties.exporter}</span><span className="table-sub">{o.parties.importer}</span></td><td><Badge>{o.customs}</Badge><span className="table-sub">{o.customsRef || '尚未登记凭证'}</span></td><td><Badge>{o.taxStatus}</Badge><span className="table-sub">{o.taxRef || '待办理后归档'}</span></td><td><div className="vertical-actions">{o.customs !== '已放行' && <button className="text-button" onClick={() => open({ type: 'recordCustoms', order: o })}>登记放行</button>}{o.taxStatus !== '已归档' && <button className="text-button" onClick={() => open({ type: 'archiveTax', order: o })}>资料归档</button>}</div></td></tr>)}</tbody></table></div></section></>; }
  function renderSettlements() { return <><div className="settlement-summary"><div><span>已交付 · 待结余额</span><strong>{money(pendingTotal)}</strong></div><div><span>已登记付款</span><strong>{money(s!.settlements.reduce((a, x) => a + x.amount, 0))}</strong></div><div><span>商户平台服务费</span><strong>¥0<em>商户平台服务免费</em></strong></div></div><div className="section-note"><CircleHelp size={18}/><span>这里只登记核验和付款记录，不发起银行转账。运输、包装等实际成本按订单约定承担。</span></div><section className="panel"><div className="panel-heading"><div><h2>商户结算台账</h2><p>按供货商分别对账，支持分批登记付款</p></div></div>{settlementRows.length ? <div className="table-scroll"><table className="data-table"><thead><tr><th>订单 / 商户</th><th>应结货款</th><th>已登记付款</th><th>未结余额</th><th>状态</th><th/></tr></thead><tbody>{settlementRows.map(r => <tr key={r.order.id + r.supplierId}><td><b>{r.order.id}</b><span className="table-sub">{supplierName(r.supplierId)}</span></td><td>{money(r.due)}</td><td>{money(r.paid)}</td><td className="numeric">{money(r.due-r.paid)}</td><td><Badge tone={r.due === r.paid ? 'green' : 'amber'}>{r.due === r.paid ? '已结清' : r.paid ? '部分结算' : '待结算'}</Badge></td><td>{isOps && r.due > r.paid ? <button className="text-button" onClick={() => open({ type: 'settle', order: r.order, supplierId: r.supplierId })}>登记付款<ArrowUpRight size={14}/></button> : <button className="text-button" onClick={() => open({ type: 'orderDetail', order: r.order })}>查看订单</button>}</td></tr>)}</tbody></table></div> : empty('暂无待结算订单', '订单完成海外签收后，会在这里生成应结记录。')}</section><section className="panel spaced"><div className="panel-heading"><div><h2>付款记录</h2><p>已登记的依据、金额和日期</p></div></div>{s!.settlements.length ? <div className="table-scroll"><table className="data-table"><thead><tr><th>付款记录</th><th>关联订单</th><th>商户</th><th>金额</th><th>凭证依据</th><th>日期</th></tr></thead><tbody>{s!.settlements.map(r => <tr key={r.id}><td>{r.id}</td><td>{r.orderId}</td><td>{supplierName(r.supplierId)}</td><td>{money(r.amount)}</td><td>{r.reference}</td><td>{dateText(r.paidAt)}</td></tr>)}</tbody></table></div> : empty('尚未登记付款')}</section></>; }
  function renderSuppliers() { return <><div className="section-note"><ShieldCheck size={18}/><span>商户准入、商品审核与渠道选品分别判断；不收取入驻费、会员费或成交佣金。</span></div><div className="supplier-grid">{s!.suppliers.filter(matches).map(x => <article className="panel supplier-card" key={x.id}><div className="supplier-top"><div className="supplier-avatar">{x.name.slice(0,1)}</div><Badge>{x.status}</Badge></div><h3>{x.name}</h3><p>{x.category} · {x.location}</p><div className="supplier-facts"><span>联系人 <b>{x.contact}</b></span><span>商品数 <b>{s!.products.filter(p => p.supplierId === x.id).length} 款</b></span><span>平台服务费 <b className="green-text">¥0</b></span></div><p className="supplier-note">{x.note}</p><button className="btn full-width" onClick={() => x.status === '待审核' ? open({ type: 'approveSupplier', id: x.id, title: x.name }) : open({ type: 'createProduct', supplierId: x.id })}>{x.status === '待审核' ? '审核供货资格' : '为商户登记商品'}<ArrowUpRight size={15}/></button></article>)}</div></>; }
  function renderIssues() { return <><div className="toolbar"><div className="tabs">{['全部','待处理','已解决'].map(t => <button className={filter === t ? 'active' : ''} key={t} onClick={() => setFilter(t)}>{t}</button>)}</div><small className="muted">待处理异常会阻断发运、签收或结算</small></div><div className="issue-list">{s!.issues.filter(i => matches(i) && (filter === '全部' || i.status === filter)).map(i => <section className="panel issue-card" key={i.id}><span className={`issue-symbol ${i.status === '已解决' ? 'resolved' : ''}`}>{i.status === '已解决' ? <CheckCircle2 size={22}/> : <AlertTriangle size={22}/>}</span><div className="issue-main"><div className="issue-title"><h3>{i.title}</h3><Badge>{i.status}</Badge></div><p>{i.detail}</p><div className="issue-meta"><span>{i.orderId}</span><span>{i.category}</span><span>{dateText(i.createdAt)}</span>{i.blocking && i.status === '待处理' && <span className="danger-text">阻断履约</span>}</div>{i.resolution && <div className="resolution"><Check size={15}/>{i.resolution}</div>}</div>{isOps && i.status === '待处理' && <button className="btn small-btn" onClick={() => open({ type: 'resolveIssue', id: i.id, title: i.title })}>跟进处理</button>}</section>)}</div>{!s!.issues.filter(i => matches(i) && (filter === '全部' || i.status === filter)).length && empty('当前没有相关异常', '如发现数量、质量或结算差异，可从订单详情发起反馈。')}</>; }
  function renderService() { return <><div className="service-intro panel"><div className="service-icon"><MessageCircle size={30}/></div><div><h2>供货服务台</h2><p>商品资料、供货协作与订单问题，在这里留下一条请求。</p><small>当前为开发验证环境，提交内容会保存在你的工作空间，不会发送给外部人员。</small></div><button className="btn primary" onClick={() => open({ type: 'createServiceTask' })}><Plus size={17}/>提交服务请求</button></div><section className="panel spaced"><div className="panel-heading"><h2>服务请求</h2></div>{s!.serviceTasks.length ? s!.serviceTasks.filter(matches).map(t => <div className="service-row" key={t.id}><div><b>{t.title}</b><p>{t.detail}</p>{t.resolution && <small>处理结果：{t.resolution}</small>}</div><Badge>{t.status}</Badge>{isOps && t.status === '待处理' && <button className="text-button" onClick={() => open({ type: 'resolveServiceTask', id: t.id, title: t.title })}>处理请求</button>}</div>) : empty('还没有服务请求', '你的请求和处理进度会保存在这里。')}</section><section className="panel spaced"><div className="panel-heading"><h2>最近操作记录</h2></div><div className="activity-list">{s!.events.slice(0,20).map(e => <div className="activity" key={e.id}><CircleDot size={15}/><div><b>{e.action}</b><p>{e.detail || e.targetId}</p></div><time>{dateText(e.at)}</time></div>)}</div></section></>; }

  async function submitForm(e: FormEvent<HTMLFormElement>) {
    e.preventDefault(); if (!modal || !s) return; const f = new FormData(e.currentTarget); const val = (key: string) => String(f.get(key) || '').trim(); const num = (key: string) => Number(f.get(key)); const cents = (key: string) => Math.round(num(key) * 100); const id = modal.order?.id || modal.id;
    const type = modal.type;
    if (type === 'createProduct' || type === 'updateProduct') return void await command(type, { id: modal.product?.id, supplierId: isSupplier ? actor.entityId : val('supplierId'), name: val('name'), category: val('category'), spec: val('spec'), unit: val('unit'), price: cents('price'), moq: num('moq'), stock: num('stock'), leadDays: num('leadDays'), note: val('note'), artwork: val('artwork') });
    if (type === 'reviewProduct') return void await command(type, { id: modal.product?.id, result: val('result'), note: val('note') });
    if (type === 'createSupplier') return void await command(type, { name: val('name'), category: val('category'), contact: val('contact'), location: val('location'), note: val('note') });
    if (type === 'approveSupplier') return void await command(type, { id, note: val('note') });
    if (type === 'createDemand') return void await command(type, { buyerId: isBuyer ? actor.entityId : val('buyerId'), title: val('title'), category: val('category'), quantity: num('quantity'), budget: cents('budget'), dueDate: val('dueDate'), destination: val('destination'), requirements: val('requirements') });
    if (type === 'createQuote') return void await command(type, { demandId: modal.demand?.id, lines: Array.from({ length: quoteLineCount }, (_, i) => ({ productId: val(`product-${i}`), quantity: num(`quantity-${i}`), unitPrice: cents(`price-${i}`) })), shipping: cents('shipping'), tax: cents('tax'), validUntil: val('validUntil'), parties: { purchaser: val('purchaser'), exporter: val('exporter'), importer: val('importer'), payee: val('payee'), delivery: val('delivery'), settlement: val('settlement') }, notes: val('notes') });
    if (type === 'confirmSupply') return void await command(type, { id, supplierId: modal.supplierId });
    if (type === 'verifyPayment') return void await command(type, { id, reference: val('reference'), amount: cents('amount') });
    if (type === 'warehouseDelivery') return void await command(type, { id, supplierId: modal.supplierId, reference: val('reference') });
    if (type === 'inspect') return void await command(type, { id, result: val('result'), quantity: num('quantity'), reference: val('reference') });
    if (['recordCustoms','archiveTax','receive'].includes(type)) return void await command(type, { id, reference: val('reference') });
    if (type === 'dispatch') return void await command(type, { id, carrier: val('carrier'), waybill: val('waybill'), eta: val('eta') });
    if (type === 'settle') return void await command(type, { id, supplierId: modal.supplierId, amount: cents('amount'), reference: val('reference'), paidAt: val('paidAt') });
    if (type === 'createIssue') return void await command(type, { orderId: id || val('orderId'), title: val('title'), detail: val('detail'), category: val('category') });
    if (type === 'resolveIssue' || type === 'resolveServiceTask') return void await command(type, { id, resolution: val('resolution') });
    if (type === 'createServiceTask') return void await command(type, { title: val('title'), detail: val('detail') });
  }
  function renderModal() {
    if (!modal || !s) return null;
    const p = modal.product; const o = modal.order ? s.orders.find(o => o.id === modal.order?.id) || modal.order : undefined; const d = modal.demand; const q = modal.quote;
    const titleMap: Record<string,string> = { createProduct: '提交供货商品', updateProduct: '更新商品资料', reviewProduct: '审核供货商品', createSupplier: '登记供货商户', approveSupplier: '审核商户准入', createDemand: '发布采购需求', createQuote: '形成渠道报价', confirmSupply: '确认供货条件', verifyPayment: '登记收款核验', warehouseDelivery: '登记国内交货', inspect: '记录到仓验货', recordCustoms: '登记通关放行', archiveTax: '登记税务资料归档', dispatch: '登记跨境发运', receive: '确认海外签收', settle: '登记商户付款', createIssue: '反馈订单异常', resolveIssue: '处理订单异常', createServiceTask: '提交服务请求', resolveServiceTask: '回复服务请求' };
    if (modal.type === 'productDetail' && p) return <Dialog title={p.name} onClose={dismiss}><div className="product-detail"><ProductArt kind={p.artwork}/><div className="detail-info"><Badge>{p.status}</Badge><p>{p.spec}</p><dl><dt>商品品类</dt><dd>{p.category}</dd><dt>起订量</dt><dd>{p.moq} {p.unit}</dd><dt>可供数量</dt><dd>{number(p.stock)} {p.unit}</dd><dt>备货周期</dt><dd>{p.leadDays} 天</dd>{!isBuyer && <><dt>供货单价</dt><dd>{money(p.price)}</dd><dt>供货商户</dt><dd>{supplierName(p.supplierId)}</dd></>}</dl>{p.note && <p className="info-note">{p.note}</p>}</div></div><div className="dialog-footer"><button className="btn" onClick={dismiss}>关闭</button><button className="btn primary" onClick={() => open({ type: isBuyer ? 'createDemand' : isOps && p.status !== '可供货' ? 'reviewProduct' : 'updateProduct', product: p })}>{isBuyer ? '发起采购需求' : isOps && p.status !== '可供货' ? '审核商品' : '更新商品资料'}</button></div></Dialog>;
    if (modal.type === 'demandDetail' && d) return <Dialog title="采购需求详情" onClose={dismiss}><div className="dialog-content"><Badge>{d.status}</Badge><h3>{d.title}</h3><p>{d.requirements}</p><dl><dt>数量</dt><dd>{d.quantity} 件</dd><dt>目标单价</dt><dd>{money(d.budget)}</dd><dt>目的地</dt><dd>{d.destination}</dd><dt>期望到货</dt><dd>{d.dueDate}</dd></dl>{isSupplier && <div className="info-note">运营按商品条件组织选品。你可完善对应商品，或提交服务请求说明供货意愿。</div>}</div><div className="dialog-footer"><button className="btn" onClick={dismiss}>关闭</button>{isSupplier && <button className="btn primary" onClick={() => open({ type: 'createServiceTask', title: `供货意向：${d.id}` })}>提交供货意向</button>}</div></Dialog>;
    if (modal.type === 'quoteDetail' && q) return <Dialog title={`报价详情 · ${q.id}`} onClose={dismiss} wide><div className="dialog-content"><div className="detail-title"><Badge>{q.status}</Badge><span>有效期至 {q.validUntil} · 人民币报价</span></div><table className="data-table"><thead><tr><th>商品 / 规格</th><th>数量</th><th>单价</th><th>小计</th></tr></thead><tbody>{q.lines.map(l => <tr key={l.productId}><td>{l.name}<span className="table-sub">{l.spec}</span></td><td>{l.quantity} {l.unit}</td><td>{money(l.unitPrice)}</td><td>{money(l.unitPrice*l.quantity)}</td></tr>)}</tbody></table><div className="quote-totals"><span>运输费用 <b>{money(q.shipping)}</b></span><span>已确认税费 <b>{money(q.tax)}</b></span><strong>报价总额 <b>{money(q.total)}</b></strong></div><dl>{Object.entries({ '实际采购方':q.parties.purchaser,'出口主体':q.parties.exporter,'进口主体':q.parties.importer,'收款主体':q.parties.payee,'交付条件':q.parties.delivery,'结算条件':q.parties.settlement }).map(([k,v]) => <div className="dl-row" key={k}><dt>{k}</dt><dd>{v}</dd></div>)}</dl><p className="info-note">{q.notes}</p>{formError && <p className="form-error">{formError}</p>}</div><div className="dialog-footer"><button className="btn" onClick={dismiss}>关闭</button>{q.status === '待确认' && <button className="btn primary" disabled={busy} onClick={() => command('acceptQuote', { id: q.id })}>{busy ? '处理中…' : '确认条款并生成订单'}</button>}</div></Dialog>;
    if (modal.type === 'orderDetail' && o) return <Dialog title={`供货订单 · ${o.id}`} onClose={dismiss} wide><div className="dialog-content"><div className="detail-title"><Badge>{o.status}</Badge><span>建立于 {dateText(o.createdAt)} · {buyerName(o.buyerId)}</span></div><div className="status-strip"><div><span>订单</span><b>{o.status}</b></div><div><span>物流</span><b>{o.logistics}</b></div><div><span>收款</span><b>{o.payment}</b></div><div><span>关务</span><b>{o.customs}</b></div><div><span>税务</span><b>{o.taxStatus}</b></div></div><h3 className="section-title">供货清单</h3><div className="order-lines">{o.lines.map(l => <div className="order-line" key={l.productId}><ProductArt kind={l.artwork} small/><div><b>{l.name}</b><small>{l.spec}</small><small>{!isBuyer && supplierName(l.supplierId)}</small></div><span>{l.quantity} {l.unit}</span><strong>{money(l.unitPrice*l.quantity)}</strong></div>)}</div><div className="order-total"><span>{isSupplier ? '本商户供货金额' : '订单总额（含约定运输与税费）'}</span><strong>{money(o.total)}</strong></div><h3 className="section-title">交付与结算约定</h3><dl>{Object.entries({ '交货与验收':o.parties.delivery,'目的地':o.destination,'期望到货':o.dueDate,'实际采购方':o.parties.purchaser,'收款主体':o.parties.payee,'结算条件':o.parties.settlement }).map(([k,v]) => <div className="dl-row" key={k}><dt>{k}</dt><dd>{v}</dd></div>)}</dl>{s.issues.filter(i => i.orderId === o.id && i.status === '待处理').map(i => <div className="warning-note" key={i.id}><AlertTriangle size={17}/><span>{i.title}：{i.detail}</span>{isOps && <button className="text-button" onClick={() => open({ type: 'resolveIssue', id: i.id, title: i.title })}>处理</button>}</div>)}{o.waybill && <div className="info-note">{o.carrier} · {o.waybill} · 预计 {o.eta} 到达</div>}<p className="tiny muted">示例工作空间 · 这里的记录不会触发实际扣款、转账或物流下单。</p>{formError && <p className="form-error">{formError}</p>}</div><div className="dialog-footer order-dialog-footer">{orderActions(o)}</div></Dialog>;
    const type = modal.type;
    return <Dialog title={titleMap[type] || '业务操作'} onClose={dismiss} wide={type === 'createQuote'}><form onSubmit={submitForm}><div className="dialog-content"><div className="form-grid">
      {(type === 'createProduct' || type === 'updateProduct') && <>{!isSupplier && <Field label="供货商户" full><select name="supplierId" required defaultValue={p?.supplierId || modal.supplierId}>{s.suppliers.map(x => <option key={x.id} value={x.id}>{x.name}</option>)}</select></Field>}<Field label="商品名称" full><input name="name" required maxLength={160} defaultValue={p?.name} placeholder="例如：藤编纹收纳篮"/></Field><Field label="品类"><select name="category" defaultValue={p?.category}>{categories.map(c => <option key={c}>{c}</option>)}</select></Field><Field label="计量单位"><input name="unit" required defaultValue={p?.unit || '个'}/></Field><Field label="规格 / 颜色 / 尺寸" full><input name="spec" required defaultValue={p?.spec} placeholder="请填写明确的商品规格"/></Field><Field label="供货单价（人民币元）"><input name="price" type="number" min="0.01" step="0.01" required defaultValue={p ? p.price/100 : ''}/></Field><Field label="起订量"><input name="moq" type="number" min="1" step="1" required defaultValue={p?.moq || 60}/></Field><Field label="可供数量"><input name="stock" type="number" min="0" step="1" required defaultValue={p?.stock || 300}/></Field><Field label="备货天数"><input name="leadDays" type="number" min="1" max="365" required defaultValue={p?.leadDays || 3}/></Field><Field label="商品示意图" hint="用于开发版展示，不代表真实商品照片"><select name="artwork" defaultValue={p?.artwork || 'basket'}>{[['basket','收纳篮'],['towel','毛巾'],['bag','帆布袋'],['bottle','水杯'],['pillow','抱枕'],['organizer','收纳套装']].map(([v,l]) => <option key={v} value={v}>{l}</option>)}</select></Field><Field label="供货补充说明" full><textarea name="note" defaultValue={p?.note} placeholder="包装、样品、货源等说明"/></Field><div className="info-note full">商品提交或修改后进入审核。供货商户无需支付平台服务费。</div></>}
      {type === 'reviewProduct' && <><div className="info-note full">{p?.name} · {p?.spec} · 供货价 {money(p?.price || 0)}</div><Field label="审核结果" full><select name="result"><option>可供货</option><option>待补充</option></select></Field><Field label="审核依据 / 待补资料" full><textarea name="note" required placeholder="记录审核过的资料、样品或需补充的内容"/></Field></>}
      {type === 'createSupplier' && <><Field label="商户名称" full><input name="name" required placeholder="经营主体或商行名称"/></Field><Field label="主营品类"><select name="category">{categories.map(c => <option key={c}>{c}</option>)}</select></Field><Field label="联系人"><input name="contact" required placeholder="姓名及联系信息"/></Field><Field label="档口 / 地址" full><input name="location" required/></Field><Field label="供货说明" full><textarea name="note"/></Field><div className="info-note full">免费登记后进入准入审核，不自动取得供货订单。</div></>}
      {type === 'approveSupplier' && <><p className="full">{modal.title}</p><Field label="主体、货源与供货能力核实记录" full><textarea name="note" required placeholder="记录已核实的信息与合作范围"/></Field></>}
      {type === 'createDemand' && <>{isOps && <Field label="采购渠道" full><select name="buyerId">{s.buyers.map(b => <option key={b.id} value={b.id}>{b.name}</option>)}</select></Field>}<Field label="采购需求名称" full><input name="title" required defaultValue={p ? `${p.name}采购` : ''} placeholder="例如：曼谷零售门店收纳用品补货"/></Field><Field label="品类"><select name="category" defaultValue={p?.category}>{categories.map(c => <option key={c}>{c}</option>)}</select></Field><Field label="采购数量"><input name="quantity" type="number" min="1" required defaultValue={p?.moq || 100}/></Field><Field label="目标单价（人民币元）" hint="填 0 表示面议"><input name="budget" type="number" min="0" step="0.01" required defaultValue="0"/></Field><Field label="期望到货日期"><input name="dueDate" type="date" min={day()} required defaultValue={day(21)}/></Field><Field label="目的地 / 收货仓" full><input name="destination" required defaultValue="泰国 · 曼谷"/></Field><Field label="商品、包装与验收要求" full><textarea name="requirements" required defaultValue={p?.spec} placeholder="填写规格、样品、包装、验收和采购安排"/></Field></>}
      {type === 'createQuote' && <><div className="info-note full">{d?.title} · 报价币种：人民币。首版按整单足额收款后组织供货。</div><div className="quote-line-editor full">{Array.from({ length: quoteLineCount }, (_, i) => <div className="quote-line-fields" key={i}><Field label={`商品 ${i+1}`}><select name={`product-${i}`} required defaultValue=""><option value="" disabled>选择已审核商品</option>{s.products.filter(x => x.status === '可供货').map(x => <option key={x.id} value={x.id}>{x.name} · {money(x.price)}/{x.unit} · 起订 {x.moq}</option>)}</select></Field><Field label="数量"><input name={`quantity-${i}`} type="number" min="1" required defaultValue={d?.quantity}/></Field><Field label="渠道单价（元）"><input name={`price-${i}`} type="number" min="0.01" step="0.01" required/></Field></div>)}<button type="button" className="text-button" onClick={() => setQuoteLineCount(x => Math.min(10,x+1))}><Plus size={15}/>增加商品</button></div><Field label="运输费用（元）"><input name="shipping" type="number" min="0" step="0.01" required defaultValue="0"/></Field><Field label="已确认税费（元）"><input name="tax" type="number" min="0" step="0.01" required defaultValue="0"/></Field><Field label="报价有效期"><input name="validUntil" type="date" min={day()} required defaultValue={day(7)}/></Field><Field label="实际采购方"><input name="purchaser" required placeholder="完整主体名称"/></Field><Field label="境内出口主体"><input name="exporter" required/></Field><Field label="泰国进口主体"><input name="importer" required/></Field><Field label="实际收款主体" full><input name="payee" required/></Field><Field label="交货地点、验收与风险约定" full><textarea name="delivery" required placeholder="明确国内交货、海外验收与责任边界"/></Field><Field label="商户结算条件" full><textarea name="settlement" required placeholder="结算触发条件、付款期限与承担方；平台服务费为 0"/></Field><Field label="费用边界与补充条款" full><textarea name="notes" required placeholder="说明费用包含/不含范围及依据。税费未确认时请勿形成正式报价。"/></Field></>}
      {type === 'confirmSupply' && o && <><div className="info-note full">{supplierName(modal.supplierId!)} · {o.id}</div><div className="full confirm-lines">{o.lines.filter(l => l.supplierId === modal.supplierId).map(l => <p key={l.productId}>{l.name} · {l.spec}<b>{l.quantity} {l.unit} / {money((l.unitCost ?? l.unitPrice)*l.quantity)}</b></p>)}</div><p className="full">{o.parties.delivery}<br/>{o.parties.settlement}</p><label className="checkbox-field full"><input type="checkbox" required/>我已核对商品、数量、供货金额与交付条件</label></>}
      {type === 'verifyPayment' && <><div className="warning-note full"><CircleHelp size={17}/>请依据已核实的收款记录登记。此操作不收款、不转账。</div><Field label="核实收款金额（人民币元）" full><input name="amount" type="number" min="0.01" step="0.01" required defaultValue={(o?.total || 0)/100}/></Field></>}
      {type === 'inspect' && <><Field label="验货结果"><select name="result"><option>通过</option><option>差异</option></select></Field><Field label="实收总数量"><input name="quantity" type="number" min="1" required defaultValue={o?.lines.reduce((a,l) => a+l.quantity,0)}/></Field><div className="info-note full">存在未解决异常或数量不一致时，不能登记为验货通过。</div></>}
      {['verifyPayment','warehouseDelivery','inspect','recordCustoms','archiveTax','receive','settle'].includes(type) && <Field label={type === 'inspect' ? '验货依据 / 差异说明' : '凭证编号与核实说明'} full hint="首版记录凭证编号及说明，暂不上传附件；演示时请注明“示例”"><textarea name="reference" required maxLength={2000} placeholder="填写可追溯的凭证编号、核实人和核实结果"/></Field>}
      {type === 'dispatch' && <><Field label="承运服务"><input name="carrier" required placeholder="实际承运商或专线"/></Field><Field label="运单号"><input name="waybill" required/></Field><Field label="预计到达日期" full><input name="eta" type="date" min={day()} required defaultValue={day(7)}/></Field><div className="info-note full">验货通过、款项核实、关务放行且无阻断异常后，才能登记发运。</div></>}
      {type === 'settle' && o && <><div className="info-note full">{supplierName(modal.supplierId!)} · 未结余额 {money(dueFor(o,modal.supplierId!)-paidFor(s,o.id,modal.supplierId!))} · 平台费 ¥0</div><Field label="本次已付款金额（人民币元）"><input name="amount" type="number" min="0.01" step="0.01" max={(dueFor(o,modal.supplierId!)-paidFor(s,o.id,modal.supplierId!))/100} required defaultValue={(dueFor(o,modal.supplierId!)-paidFor(s,o.id,modal.supplierId!))/100}/></Field><Field label="实际付款日期"><input name="paidAt" type="date" max={day()} required defaultValue={day()}/></Field></>}
      {type === 'createIssue' && <>{!o && <Field label="关联订单" full><select name="orderId" required>{s.orders.map(x => <option key={x.id}>{x.id}</option>)}</select></Field>}<Field label="问题类型"><select name="category">{['验货差异','库存或交期','关务资料','物流异常','费用与结算','售后问题'].map(x => <option key={x}>{x}</option>)}</select></Field><Field label="问题标题"><input name="title" required/></Field><Field label="问题详情与证据说明" full><textarea name="detail" required/></Field></>}
      {['resolveIssue','resolveServiceTask'].includes(type) && <><p className="full">{modal.title}</p><Field label="处理结果与依据" full><textarea name="resolution" required placeholder="记录采取的措施、核实结果和后续安排"/></Field></>}
      {type === 'createServiceTask' && <><Field label="请求主题" full><input name="title" required defaultValue={modal.title} placeholder="例如：需要协助补充商品资料"/></Field><Field label="具体问题与期待的帮助" full><textarea name="detail" required/></Field></>}
    </div>{formError && <div className="form-error" role="alert">{formError}</div>}</div><div className="dialog-footer"><button type="button" className="btn" onClick={dismiss}>取消</button><button type="submit" className="btn primary" disabled={busy}>{busy ? <Loader2 className="spin" size={16}/> : <Check size={16}/>} {busy ? '正在保存' : type === 'createQuote' ? '保存正式报价' : '确认并保存'}</button></div></form></Dialog>;
  }

  return <div className="app-shell">
    {mobileOpen && <button className="sidebar-scrim" aria-label="关闭导航" onClick={() => setMobileOpen(false)}/>}
    <aside className={`sidebar ${mobileOpen ? 'mobile-open' : ''}`}><button className="brand" onClick={() => navigate('dashboard')}><span className="brand-symbol"><Boxes size={26}/></span><span><strong>螺蛳湾<span>海外供货</span></strong><small>LUOSI TRADE</small></span></button><div className="workspace-label"><span className="live-dot"/>泰国首发 · 供货协作</div><div className="nav-label">业务工作空间</div><nav>{allowedNav.map(n => <button key={n.id} className={page === n.id ? 'nav-item active' : 'nav-item'} onClick={() => navigate(n.id)}><n.icon size={19}/><span>{isSupplier && n.id === 'products' ? '我的货品' : isBuyer && n.id === 'orders' ? '采购订单' : isSupplier && n.id === 'settlements' ? '我的结算' : n.title}</span>{n.id === 'issues' && activeIssues.length > 0 && <em>{activeIssues.length}</em>}</button>)}</nav><div className="sidebar-bottom"><div className="free-card"><span><Leaf size={18}/>好货出海，轻松起步</span><p>商户入驻与平台服务免费<br/>按商品和供货能力审核</p></div><button className={`nav-item ${page === 'service' ? 'active' : ''}`} onClick={() => navigate('service')}><CircleHelp size={19}/><span>帮助与服务</span><ArrowUpRight size={15}/></button><div className="sidebar-signature">螺蛳湾商户 · 海外渠道 · 履约协作</div></div></aside>
    <div className="main-shell"><header className="topbar"><div className="topbar-left"><button className="icon-button mobile-menu" aria-label="打开导航" onClick={() => setMobileOpen(true)}><Menu size={21}/></button><span className="breadcrumb">工作空间<ChevronRight size={13}/><b>{pageTitle}</b></span></div><div className="topbar-actions"><label className="search-field"><Search size={17}/><input placeholder="搜索当前页面…" aria-label="搜索当前页面" value={query} onChange={e => setQuery(e.target.value)}/>{query && <button className="icon-button" aria-label="清除搜索" onClick={() => setQuery('')}><X size={14}/></button>}</label><button className="icon-button notification" aria-label="查看待处理事项" onClick={() => navigate('issues')}><Bell size={20}/>{activeIssues.length > 0 && <i/>}</button><span className="topbar-divider"/><span className="avatar">{isOps ? '运' : isSupplier ? '商' : '采'}</span><div className="user-label"><b>{isSupplier ? supplier?.name || currentRole.title : currentRole.title}</b><small>{displayName}</small></div></div></header>
    <div className="demo-bar"><span><CircleDot size={14}/><b>开发验证版</b><span className="demo-explain">示例业务数据 · 独立私有工作空间</span></span><div className="role-controls"><label>体验身份<select aria-label="切换体验身份" value={actor.role} disabled={busy} onChange={e => changeRole(e.target.value as Role)}>{roles.map(r => <option key={r.id} value={r.id}>{r.title}</option>)}</select></label>{!isOps && <select aria-label="选择体验商户或采购方" value={actor.entityId} disabled={busy} onChange={e => { setWorkspace(null); setActor(a => ({ ...a, entityId: e.target.value })); }}>{(isSupplier ? supplierOptions : buyerOptions).map(x => <option key={x.id} value={x.id}>{x.name}</option>)}</select>}</div></div>
    <main className="main-content"><div className="page-heading"><div><div className="page-kicker">{page === 'dashboard' ? 'OVERVIEW' : 'LUOSI TRADE / ' + page.toUpperCase()}</div><h1>{page === 'dashboard' ? (isSupplier ? '商户工作台' : isBuyer ? '采购工作台' : '运营工作台') : pageTitle}</h1><p>{page === 'dashboard' ? `${new Date().toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai',month:'long',day:'numeric',weekday:'long'})}，每一笔供货，都有清楚的下一步。` : pageDescriptions[page]}</p></div><div className="heading-actions">{page === 'dashboard' ? <button className="btn" onClick={() => load()} disabled={loading}><RefreshCw size={15} className={loading ? 'spin' : ''}/>刷新数据</button> : page === 'products' && !isBuyer ? <button className="btn primary" onClick={() => open({ type: 'createProduct' })}><Plus size={17}/>提交商品</button> : page === 'demands' && !isSupplier ? <button className="btn primary" onClick={() => open({ type: 'createDemand' })}><Plus size={17}/>发布采购需求</button> : page === 'orders' ? <button className="btn" onClick={exportOrders}><Download size={16}/>导出订单</button> : page === 'suppliers' ? <button className="btn primary" onClick={() => open({ type: 'createSupplier' })}><Plus size={17}/>登记商户</button> : page === 'issues' ? <button className="btn primary" onClick={() => open({ type: 'createIssue' })}><Plus size={17}/>反馈异常</button> : null}</div></div>
    {error ? <div className="error-state"><AlertTriangle size={30}/><h2>工作空间暂时无法读取</h2><p>{error}</p><button className="btn primary" onClick={() => load()}>重新加载</button></div> : loading && !s ? <div className="loading-state"><Loader2 className="spin" size={28}/><p>正在读取你的工作空间…</p></div> : s && <>{page === 'dashboard' && renderDashboard()}{page === 'products' && renderProducts()}{page === 'demands' && renderDemands()}{page === 'orders' && <><div className="toolbar"><div className="tabs scroll-tabs">{['全部','待确认','待启动','备货中','待验货','待发运','运输中','已交付','已关闭'].map(t => <button key={t} className={filter === t ? 'active' : ''} onClick={() => setFilter(t)}>{t}</button>)}</div></div><section className="panel">{orderTable(orders.filter(o => filter === '全部' || o.status === filter))}</section></>}{page === 'logistics' && renderLogistics()}{page === 'documents' && renderDocuments()}{page === 'settlements' && renderSettlements()}{page === 'suppliers' && renderSuppliers()}{page === 'issues' && renderIssues()}{page === 'service' && renderService()}</>}
    <footer className="page-footer"><span>螺蛳湾 · 海外供货平台</span><span>做好你的货，让生意走向更远。</span></footer></main></div>
    {renderModal()}{toast && <div className="toast" role="status"><CheckCircle2 size={18}/>{toast}<button className="icon-button" aria-label="关闭提示" onClick={() => setToast('')}><X size={15}/></button></div>}
  </div>;
}
